package local.skyfamily;
import android.graphics.*;import android.view.*;import android.os.SystemClock;import android.content.SharedPreferences;import org.json.*;import java.util.*;
final class ThemeArt {
 static final String[] MODES={"auto","spring","summer","fall","winter","christmas","halloween","stpatrick","birthday"};static final String[] LABELS={"Automatic / local date","Spring","Summer","Fall","Winter","Christmas","Halloween","St. Patrick's Day","Birthday"};static final String[] SCENES={"off","auto","leaves","rain","snow","snowmen"};
 static JSONArray birthdays(SharedPreferences p){try{return new JSONArray(p.getString("visual.birthdays","[]"));}catch(Exception e){return new JSONArray();}}
 static String dateKey(Calendar now){return String.format(Locale.US,"%02d-%02d",now.get(Calendar.MONTH)+1,now.get(Calendar.DAY_OF_MONTH));}
 static ArrayList<String> today(SharedPreferences p){ArrayList<String> names=new ArrayList<>();String key=dateKey(Calendar.getInstance());JSONArray all=birthdays(p);for(int i=0;i<all.length();i++){JSONObject b=all.optJSONObject(i);if(b!=null&&key.equals(b.optString("date")))names.add(b.optString("name"));}return names;}
 static String active(SharedPreferences p){String manual=p.getString("visual.mode","auto");if(!manual.equals("auto"))return Arrays.asList(MODES).contains(manual)?manual:"winter";Calendar now=Calendar.getInstance();int month=now.get(Calendar.MONTH)+1,day=now.get(Calendar.DAY_OF_MONTH);if(!today(p).isEmpty())return "birthday";if(month==12&&day<=26)return "christmas";if(month==10&&day>=15)return "halloween";if(month==3&&day>=10&&day<=17)return "stpatrick";boolean south=p.getString("visual.hemisphere","auto").equals("south");if(p.getString("visual.hemisphere","auto").equals("auto"))try{south=new JSONObject(p.getString("planetary.location","{}")).optDouble("latitude",0)<0;}catch(Exception ignored){}int season=month>=3&&month<=5?0:month>=6&&month<=8?1:month>=9&&month<=11?2:3;if(south)season=(season+2)%4;return new String[]{"spring","summer","fall","winter"}[season];}
 static class Palette{int bg,rail,surface,accent,muted=0xffb5c0d5;String name;Palette(String n,int b,int r,int s,int a){name=n;bg=b;rail=r;surface=s;accent=a;}}
 static Palette palette(SharedPreferences p){String name=active(p);if(name.equals("spring"))return new Palette(name,0xff101e25,0xff142a30,0xff21383d,0xffa9e5c4);if(name.equals("summer"))return new Palette(name,0xff101e30,0xff152b40,0xff213b50,0xffffd68d);if(name.equals("fall"))return new Palette(name,0xff221a1c,0xff302124,0xff443033,0xffefbc82);if(name.equals("christmas"))return new Palette(name,0xff10231f,0xff173029,0xff234438,0xffffc2bd);if(name.equals("halloween"))return new Palette(name,0xff1d1728,0xff2c2038,0xff3b2b48,0xffffb576);if(name.equals("stpatrick"))return new Palette(name,0xff10251f,0xff15362c,0xff21483a,0xffb7e893);if(name.equals("birthday"))return new Palette(name,0xff211a32,0xff302440,0xff453355,0xffefb6d9);return new Palette(name,0xff111d30,0xff182a43,0xff233a55,0xffc6e8ff);}
 static String scene(SharedPreferences p){String scene=p.getString("visual.scene","off");if(!scene.equals("auto"))return scene;String theme=active(p);return theme.equals("fall")||theme.equals("halloween")?"leaves":theme.equals("spring")?"rain":theme.equals("winter")||theme.equals("christmas")?"snowmen":"off";}
 static class Scene extends View{final String kind;final boolean animate;Paint p=new Paint(3);Scene(SeasonActivity host,String k,boolean motion){super(host);kind=k;animate=motion;setContentDescription("Decorative "+k+" scene");}protected void onDraw(Canvas canvas){canvas.drawColor(0xff142137);float w=getWidth(),h=getHeight(),t=animate?SystemClock.elapsedRealtime()/1000f:0;p.setStyle(Paint.Style.FILL);if(kind.equals("snowmen")){p.setColor(0xffe5f1ff);canvas.drawOval(new RectF(-w*.1f,h*.75f,w*1.1f,h*1.4f),p);for(int i=0;i<2;i++){float x=w*(i==0?.24f:.73f),r=h*.16f;p.setColor(Color.WHITE);canvas.drawCircle(x,h*.68f,r,p);canvas.drawCircle(x,h*.43f,r*.72f,p);p.setColor(0xff233249);canvas.drawCircle(x-r*.25f,h*.4f,2,p);canvas.drawCircle(x+r*.25f,h*.4f,2,p);canvas.drawRect(x-r*.8f,h*.2f,x+r*.8f,h*.26f,p);canvas.drawRect(x-r*.5f,h*.08f,x+r*.5f,h*.23f,p);p.setColor(0xffeeaa61);Path nose=new Path();nose.moveTo(x,h*.44f);nose.lineTo(x+r*.9f,h*.47f);nose.lineTo(x,h*.5f);nose.close();canvas.drawPath(nose,p);}}for(int i=0;i<34;i++){float x=((i*73%997)/997f*w+(float)Math.sin(t*.4+i)*15+w)%w,y=((i*137%991)/991f*h+t*(kind.equals("rain")?90:kind.equals("leaves")?22:16))%h;if(kind.equals("rain")){p.setColor(0xff779ecb);p.setStrokeWidth(2);canvas.drawLine(x,y,x-4,y+14,p);}else if(kind.equals("leaves")){p.setColor(i%2==0?0xffdda366:0xffaa7555);canvas.save();canvas.rotate(i*23+t*20,x,y);canvas.drawOval(new RectF(x-4,y-8,x+4,y+8),p);canvas.restore();}else{p.setColor(0xffe0efff);canvas.drawCircle(x,y,1+i%3,p);}}if(animate&&isShown()&&getWindowVisibility()==VISIBLE)postInvalidateDelayed(67);}}
 static class SantaDemo extends View{Paint p=new Paint(3);float progress=0;boolean play=false;long last;SantaDemo(SeasonActivity host){super(host);setContentDescription("Fictional Santa journey simulation. Not live tracking.");}protected void onDraw(Canvas c){long now=SystemClock.elapsedRealtime();if(play&&last>0)progress=(progress+(now-last)/90000f)%1;last=now;c.drawColor(0xff15243e);float w=getWidth(),h=getHeight();p.setColor(0xff38577d);p.setStrokeWidth(2);p.setStyle(Paint.Style.STROKE);c.drawOval(new RectF(w*.12f,h*.12f,w*.88f,h*.9f),p);for(int i=1;i<4;i++)c.drawOval(new RectF(w*(.12f+i*.07f),h*.12f,w*(.88f-i*.07f),h*.9f),p);for(int i=1;i<4;i++)c.drawLine(w*.15f,h*(.15f+i*.18f),w*.85f,h*(.15f+i*.18f),p);Path route=new Path();for(int i=0;i<=100;i++){float x=w*(.15f+.7f*i/100),y=h*(.5f+.2f*(float)Math.sin(i/100f*Math.PI*4));if(i==0)route.moveTo(x,y);else route.lineTo(x,y);}p.setColor(0xff91b4e5);c.drawPath(route,p);float x=w*(.15f+.7f*progress),y=h*(.5f+.2f*(float)Math.sin(progress*Math.PI*4));p.setStyle(Paint.Style.FILL);p.setColor(0xffef777b);c.drawCircle(x,y,12,p);p.setColor(Color.WHITE);p.setTextSize(15);p.setTextAlign(Paint.Align.CENTER);c.drawText("S",x,y+5,p);p.setTextSize(Math.max(12,h*.055f));c.drawText("SIMULATION / NOT LIVE",w/2,h*.1f,p);if(play&&isShown()&&getWindowVisibility()==VISIBLE)postInvalidateDelayed(67);}}
}
